function SupportChatView() {
  const { data, loading, error, reload } = useFetch(() => api.supportMessages(), []);
  const [draft, setDraft] = useState("");
  const send = useAction(() => api.sendSupportMessage(draft.trim()));
  const messages = data?.messages ?? [];

  function submit() {
    if (!draft.trim()) return;
    send.run().then(() => { setDraft(""); reload(); }).catch(() => {});
  }

  return (
    <div className="screen">
      <p className="hint" style={{ marginBottom: 14 }}>
        راسل فريق جملة هنا لأي استفسار أو مشكلة، وسيرد عليك أقرب وقت ممكن.
      </p>
      <div className="chat-panel">
        <div className="chat-thread chat-thread-tall">
          {loading ? <Spinner label="جارٍ التحميل…" />
           : error ? <ErrorState message={error} onRetry={reload} />
           : !messages.length ? <p className="chat-empty">لا توجد رسائل بعد — اكتب أول رسالة لك للدعم الفني.</p>
           : messages.map((m) => (
              <div className={"chat-bubble " + (m.sender_role === "actor" ? "chat-bubble-user" : "chat-bubble-support")} key={m.id}>
                <span>{m.body}</span>
                <span className="chat-time">{new Date(m.created_at).toLocaleTimeString("ar", { hour: "2-digit", minute: "2-digit" })}</span>
              </div>
            ))}
        </div>
        <div className="chat-input-row">
          <input className="chat-input" placeholder="اكتب رسالتك..." value={draft}
            onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
          <button className="chat-send" onClick={submit} disabled={send.pending} aria-label="إرسال"><Send size={17} /></button>
        </div>
        {send.error && <p className="field-error">{send.error}</p>}
      </div>
    </div>
  );
}

/* ---------------------- شريط فلترة التاريخ (من/إلى) ---------------------- */

const tripoliDay = (offsetDays = 0) => {
  const d = new Date(Date.now() + offsetDays * 86400000);
  return d.toLocaleDateString("en-CA", { timeZone: "Africa/Tripoli" });
};
const EMPTY_RANGE = { from: "", to: "" };
// يحوّل المدى إلى باراميترات للـ API (فاضي = بدون فلتر)
const rangeParams = (r) => ({ from: r?.from || undefined, to: r?.to || undefined });
const rangeLabel = (r) => (r?.from || r?.to)
  ? `الفترة: ${r.from || "البداية"} إلى ${r.to || "اليوم"}` : "";

function DateRangeBar({ value, onChange }) {
  const v = value || EMPTY_RANGE;
  const set = (patch) => onChange({ ...v, ...patch });
  const today = tripoliDay();
  const monthStart = today.slice(0, 8) + "01";
  const chips = [
    { label: "اليوم", r: { from: today, to: today } },
    { label: "7 أيام", r: { from: tripoliDay(-6), to: today } },
    { label: "هذا الشهر", r: { from: monthStart, to: today } },
    { label: "الكل", r: EMPTY_RANGE },
  ];
  const active = (r) => r.from === v.from && r.to === v.to;
  const invalid = v.from && v.to && v.from > v.to;
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", marginBottom: 8 }}>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, flex: "1 1 140px", minWidth: 0 }}>
          من
          <input type="date" lang="en-GB" dir="ltr" className="field-input" style={{ width: "100%", minWidth: 0, marginBottom: 0 }}
            value={v.from} max={v.to || undefined} onChange={(e) => set({ from: e.target.value })} />
        </label>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, flex: "1 1 140px", minWidth: 0 }}>
          إلى
          <input type="date" lang="en-GB" dir="ltr" className="field-input" style={{ width: "100%", minWidth: 0, marginBottom: 0 }}
            value={v.to} min={v.from || undefined} onChange={(e) => set({ to: e.target.value })} />
        </label>
        {(v.from || v.to) && (
          <button className="link-btn" onClick={() => onChange(EMPTY_RANGE)} aria-label="مسح الفترة">✕ مسح</button>
        )}
      </div>
      <div className="chip-row" style={{ marginBottom: 0, flexWrap: "wrap", overflowX: "visible", paddingBottom: 0 }}>
        {chips.map((c) => (
          <button key={c.label} className={"chip" + (active(c.r) ? " chip-active" : "")}
            onClick={() => onChange(c.r)}>{c.label}</button>
        ))}
      </div>
      {invalid && <p className="field-error">تاريخ البداية بعد تاريخ النهاية</p>}
    </div>
  );
}

/* -------------------------- الطلبيات -------------------------- */

function OrdersView({ onOpen }) {
  const [status, setStatus] = useState("all");
  const [range, setRange] = useState(EMPTY_RANGE);
  const filters = [
    { id: "all", label: "الكل" },
    { id: "sent", label: "جديدة" },
    { id: "preparing", label: "قيد التجهيز" },
    { id: "shortage", label: "بها نقص" },
    { id: "ready", label: "جاهزة" },
    { id: "picked_up", label: "تم الاستلام" },
  ];

  const { data, loading, error, reload } = useFetch(
    (signal) => api.orders({ ...(status === "all" ? {} : { status }), ...rangeParams(range) }, signal),
    [status, range.from, range.to]
  );

  const newCount = (data ?? []).filter((p) => p.status === "sent").length;

  return (
    <div className="screen">
      <h2 className="section-heading">طلبياتك الواردة</h2>

      {status === "all" && newCount > 0 && (
        <div className="alert-banner">
          <AlertTriangle size={16} />
          <span>لديك {newCount} {newCount === 1 ? "طلبية جديدة" : "طلبيات جديدة"} بانتظار تأكيد التوفر</span>
        </div>
      )}

      <DateRangeBar value={range} onChange={setRange} />

      <div className="chip-row">
        {filters.map((f) => (
          <button key={f.id} className={"chip" + (status === f.id ? " chip-active" : "")}
            onClick={() => setStatus(f.id)}>{f.label}</button>
        ))}
      </div>

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !data?.length ? <Centered><Package size={24} /><p>لا توجد طلبيات في هذه الحالة</p></Centered>
       : (
        <div className="ledger-list">
          {data.map((p) => (
            <button className="order-row" key={p.order_supplier_id}
              onClick={() => onOpen(p.order_supplier_id)}>
              <div className="order-row-top">
                <span className="order-row-id">{p.order_number}</span>
                <span className="status-pill">{partLabel(p.status)}</span>
              </div>
              <span className="order-row-meta">
                {p.customer_name} · {String(p.created_at).slice(0, 10)} ·{" "}
                {p.fulfillment === "pickup" ? "استلام شخصي" : "توصيل"}
              </span>
              <div className="order-row-bottom" style={{ justifyContent: "flex-end" }}>
                <span className="order-row-total">{money(p.subtotal)}</span>
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

