function downloadSupplierInvoice(part, items, subtotal) {
  const w = window.open("", "_blank");
  if (!w) return alert("يرجى السماح بالنوافذ المنبثقة لعرض الفاتورة.");
  w.document.open(); w.document.write(buildSupplierInvoiceHTML({ part, items, subtotal })); w.document.close();
}

function PartDetailView({ partId, onDone }) {
  // نجلب كل الطلبيات ثم نلتقط الجزء المطلوب — الخادم يقصر النتيجة على هذا المورد
  const list = useFetch((signal) => api.orders(undefined, signal), []);
  const part = (list.data ?? []).find((p) => p.order_supplier_id === partId);

  const detail = useFetch(
    (signal) => api.order(part.order_id, signal),
    [part?.order_id],
    { skip: !part }
  );

  const [draft, setDraft] = useState({});   // { itemId: { availability, qty } }

  const confirm = useAction((items) => api.setAvailability(partId, { items }));
  const pickup = useAction((paid, amount) => api.confirmPickup(partId, paid, amount));
  const markReady = useAction(() => api.markSupplierPartReady(partId));

  if (list.loading) return <Spinner />;
  if (list.error) return <ErrorState message={list.error} onRetry={list.reload} />;
  if (!part) return <Centered><Package size={24} /><p>تعذّر العثور على الطلبية</p></Centered>;

  const myPart = detail.data?.suppliers?.find((s) => s.id === partId);
  const items = myPart?.items ?? [];
  const locked = part.status !== "sent";

  // حالة الدفع بالحوالة (للاستلام الشخصي): خالصة / باقي مبلغ على الزبون / بانتظار تأكيد الإدارة
  const ord = detail.data;
  const isTransferPickup = part.fulfillment === "pickup" && ord?.payment_method === "transfer"
    && !["picked_up", "closed", "cancelled"].includes(part.status);
  const dueNow = Number(myPart?.due_now || 0);
  const transferWaiting = isTransferPickup && Number(ord?.paid_amount || 0) <= 0;
  const orderRemaining = Math.max(0, Number(ord?.grand_total || 0) - Number(ord?.paid_amount || 0));
  const transferPaidInFull = isTransferPickup && !transferWaiting && dueNow <= 0 && orderRemaining <= 0;
  const transferHasDue = isTransferPickup && !transferWaiting && dueNow > 0;
  // الطلبية فيها متبقي بس مورد ثاني هو اللي مكلّف يستلمه (قرار الإدارة أو التقسيم)
  const transferOtherCollects = isTransferPickup && !transferWaiting && dueNow <= 0 && orderRemaining > 0;
  const collectorName = (ord?.suppliers ?? []).find((s) => s.supplier_id === ord?.remaining_collector_id)?.supplier_name;

  function setItem(itemId, availability, qty) {
    setDraft((d) => ({ ...d, [itemId]: { availability, qty } }));
  }

  function currentFor(item) {
    // البنود اللي ما انلمست بعد (التوفر NULL في القاعدة أو "pending") تظهر "متوفر كامل" بالكمية المطلوبة،
    // وهي نفس القيمة اللي تنرسل — ما نرسل null أبدًا
    const stored = ["full", "partial", "out"].includes(item.availability) ? item.availability : "full";
    const storedQty = stored === "full" ? item.qty_requested
      : stored === "out" ? 0
      : (item.qty_confirmed ?? item.qty_requested);
    return draft[item.id] ?? { availability: stored, qty: storedQty };
  }

  const confirmedTotal = items.reduce((s, i) => {
    const c = currentFor(i);
    const qty = c.availability === "full" ? i.qty_requested : c.availability === "out" ? 0 : c.qty;
    return s + i.unit_price * qty;
  }, 0);

  async function submitAvailability() {
    const payload = items.map((i) => {
      const c = currentFor(i);
      const availability = ["full", "partial", "out"].includes(c.availability) ? c.availability : "full";
      return {
        orderItemId: i.id,
        availability,
        qtyConfirmed: availability === "full" ? Number(i.qty_requested)
                    : availability === "out" ? 0 : Number(c.qty) || 0,
      };
    });
    await confirm.run(payload).then(onDone).catch(() => {});
  }

  return (
    <div className="screen">
      <div className="order-detail-head">
        <span className="order-row-id">{part.order_number}</span>
        <span className="status-pill">{partLabel(part.status)}</span>
      </div>
      <p className="order-row-meta">{part.customer_name} · {String(part.created_at).slice(0, 10)}</p>
      <p className="order-row-meta" style={{ marginBottom: 14 }}>
        {part.fulfillment === "pickup" ? <Store size={13} /> : <Truck size={13} />}{" "}
        {part.fulfillment === "pickup" ? "استلام شخصي من العميل" : "توصيل عبر جملة"}
      </p>

      {part.supplier_note && (
        <div className="note-block">
          <span className="note-label">ملاحظة العميل</span>
          <p>{part.supplier_note}</p>
        </div>
      )}

      {detail.loading ? <Spinner label="جارٍ تحميل الأصناف…" />
       : detail.error ? <ErrorState message={detail.error} onRetry={detail.reload} />
       : (
        <>
          <div className="invoice-block">
            <div className="invoice-head">
              <span>الأصناف المطلوبة</span>
              <div className="invoice-head-right">
                <span className="invoice-head-count">{items.length} صنف</span>
                <button className="invoice-action-btn" onClick={() => downloadSupplierInvoice(part, items, myPart?.subtotal ?? confirmedTotal)}>
                  <FileText size={14} /> PDF
                </button>
              </div>
            </div>
            {items.map((item) => {
              const c = currentFor(item);
              return (
                <div className="supplier-item-row" key={item.id}>
                  <div className="supplier-item-top">
                    <span className="invoice-line-name">{item.product_name} <i>({item.unit})</i></span>
                    <span className="invoice-line-price">{money(item.unit_price)}</span>
                  </div>
                  <span className="supplier-item-qty">الكمية المطلوبة: {item.qty_requested}</span>

                  <div className="avail-row">
                    {["full", "partial", "out"].map((k) => (
                      <button key={k} disabled={locked}
                        className={"avail-btn avail-btn-" + k + (c.availability === k ? " avail-btn-active" : "")}
                        onClick={() => setItem(item.id, k, k === "full" ? item.qty_requested : k === "out" ? 0 : c.qty)}>
                        {AVAIL_LABELS[k]}
                      </button>
                    ))}
                  </div>

                  {c.availability === "partial" && (
                    <div className="confirmed-qty-row">
                      <span>الكمية المتوفرة الآن:</span>
                      <input type="number" min="0" max={item.qty_requested} className="qty-input"
                        disabled={locked} value={c.qty}
                        onChange={(e) => setItem(item.id, "partial",
                          Math.max(0, Math.min(item.qty_requested, Number(e.target.value) || 0)))} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          <div className="summary-block">
            <div className="summary-row summary-total">
              <span>قيمة الأصناف المؤكدة</span><b>{money(confirmedTotal)}</b>
            </div>
          </div>

          {confirm.error && <p className="field-error">{confirm.error}</p>}
          {pickup.error && <p className="field-error">{pickup.error}</p>}
          {markReady.error && <p className="field-error">{markReady.error}</p>}

          {!locked && (
            <button className="btn-primary" disabled={confirm.pending} onClick={submitAvailability}>
              {confirm.pending ? "جارٍ الإرسال…" : "تأكيد التوفر وبدء التجهيز"}
            </button>
          )}

          {transferPaidInFull && (
            <div className="stamp stamp-done">
              <span>✅ الطلبية خالصة — مدفوعة بالكامل بالحوالة. سلّمها للعميل بدون تحصيل أي مبلغ.</span>
            </div>
          )}
          {transferHasDue && (
            <div className="stamp stamp-waiting">
              <span>⚠️ باقي على الزبون <b>{money(dueNow)}</b> — لازم تستلمه نقدًا وتؤكد الاستلام قبل تسليم الطلبية.</span>
            </div>
          )}
          {transferOtherCollects && (
            <div className="stamp stamp-waiting">
              <span>
                ℹ️ باقي على الزبون {money(orderRemaining)} — {collectorName ? `يستلمه ${collectorName}` : "يستلمه مورد آخر"}.
                سلّم فاتورتك بدون تحصيل أي مبلغ.
              </span>
            </div>
          )}
          {transferWaiting && (
            <div className="stamp stamp-waiting">
              <span>⏳ الحوالة لم تُؤكَّد من الإدارة بعد — لا تسلّم الطلبية قبل تأكيد الإدارة.</span>
            </div>
          )}

          {part.fulfillment === "pickup" && part.status === "ready" && (
            <>
              <button className="btn-primary" disabled={pickup.pending || transferWaiting || detail.loading}
                onClick={() => (transferHasDue ? pickup.run(true, dueNow) : pickup.run(true))
                  .then(onDone).catch(() => {})}>
                <Check size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} />
                {transferHasDue
                  ? `استلمت المتبقي ${money(dueNow)} وسلّمت الطلبية`
                  : transferPaidInFull
                    ? "تأكيد حضور العميل وتسليم الطلبية (خالصة)"
                    : transferOtherCollects
                      ? "تأكيد حضور العميل وتسليم فاتورتي"
                      : "تأكيد حضور العميل واستلام قيمة الفاتورة"}
              </button>
              <p className="hint hint-center">
                {transferHasDue
                  ? "لا يتم التسليم إلا بعد تأكيد استلام المبلغ المتبقي."
                  : "لا يُعتبر الجزء مستلمًا دون تأكيد الدفع أو اعتماد الحوالة."}
              </p>
            </>
          )}

          {part.status === "preparing" && (
            <>
              <button className="btn-primary" disabled={markReady.pending}
                onClick={() => markReady.run().then(onDone).catch(() => {})}>
                <Check size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} />
                {markReady.pending ? "جارٍ التحديث…"
                  : part.fulfillment === "pickup" ? "تم التجهيز، جاهز للاستلام" : "تم التجهيز، جاهز للتسليم"}
              </button>
              <p className="hint hint-center">
                {part.fulfillment === "pickup"
                  ? 'بعد الضغط، ستنتقل الفاتورة إلى حالة "جاهزة" بانتظار حضور العميل.'
                  : 'بعد الضغط، ستنتقل الفاتورة إلى حالة "جاهزة" بانتظار إسناد مندوب من الإدارة.'}
              </p>
            </>
          )}

          {locked && part.status === "pending" && (
            <div className="stamp stamp-waiting">
              <span>هذه الطلبية بانتظار اعتماد الإدارة — ستتمكن من تأكيد التوفر بمجرد إرسالها إليك رسميًا</span>
            </div>
          )}
          {locked && part.status === "ready" && part.fulfillment === "pickup" && (
            <div className="stamp stamp-waiting">
              <span>الفاتورة جاهزة — بانتظار حضور العميل للاستلام</span>
            </div>
          )}
          {locked && part.status === "ready" && part.fulfillment !== "pickup" && (
            <div className="stamp stamp-waiting">
              <span>الفاتورة جاهزة — بانتظار إسناد مندوب توصيل من الإدارة</span>
            </div>
          )}
          {locked && !["preparing", "pending", "ready"].includes(part.status) && (
            <div className="stamp stamp-done"><span>تمت معالجة هذا الجزء</span></div>
          )}
        </>
      )}

      <h2 className="subsection-heading" style={{ marginTop: 20 }}>الدردشة مع إدارة جملة</h2>
      <SupplierChatPanel orderId={part.order_id} orderSupplierId={partId} />
    </div>
  );
}

function SupplierChatPanel({ orderId, orderSupplierId }) {
  const { data, loading, error, reload } = useFetch(
    () => api.orderMessages(orderId, orderSupplierId), [orderId, orderSupplierId]
  );
  const [draft, setDraft] = useState("");
  const send = useAction(() => api.sendOrderMessage(orderId, { body: draft.trim(), orderSupplierId }));

  function submit() {
    if (!draft.trim()) return;
    send.run().then(() => { setDraft(""); reload(); }).catch(() => {});
  }

  return (
    <div className="chat-panel">
      <div className="chat-thread">
        {loading ? <Spinner label="جارٍ التحميل…" />
         : error ? <ErrorState message={error} onRetry={reload} />
         : !data?.length ? <p className="chat-empty">راسل إدارة جملة هنا لو عندك أي استفسار بخصوص هذه الطلبية.</p>
         : data.map((m, i) => (
            <div className={"chat-bubble " + (m.sender_type === "supplier" ? "chat-bubble-user" : "chat-bubble-support")} key={i}>
              <span>{m.body}</span>
              <span className="chat-time">{new Date(m.created_at).toLocaleTimeString("ar", { hour: "2-digit", minute: "2-digit" })}</span>
            </div>
          ))}
      </div>
      <div className="chat-input-row">
        <input className="chat-input" placeholder="اكتب رسالتك..." value={draft}
          onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
        <button className="chat-send" onClick={submit} disabled={send.pending} aria-label="إرسال"><Send size={17} /></button>
      </div>
      {send.error && <p className="field-error">{send.error}</p>}
    </div>
  );
}

/* -------------------------- المنتجات -------------------------- */

function stockTag(qty) {
  if (qty <= 0) return { text: "غير متوفر", tone: "muted" };
  if (qty < 10) return { text: "كمية محدودة", tone: "amber" };
  return { text: "متوفر", tone: "success" };
}

function ProductsView() {
  const [query, setQuery] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [showVouchers, setShowVouchers] = useState(false);
  const [showBulkImages, setShowBulkImages] = useState(false);
  const [exporting, setExporting] = useState(false);
  const { data, loading, error, reload, setData } = useFetch((signal) => api.products(undefined, signal), []);
  const { data: meData } = useFetch(() => api.me(), []);
  const sections = meData?.sections ?? [];

  const q = query.trim();
  const visible = (data ?? []).filter((p) => !q || p.name.includes(q) || p.unit.includes(q)
    || (p.supplier_sku && p.supplier_sku.includes(q)));

  function exportExcel() {
    setExporting(true);
    import("xlsx").then((XLSX) => {
      // نفس ترتيب أعمدة نموذج الاستيراد بالضبط، عشان الملف يصلح يترفع من جديد بعد التعديل
      // الصنف اللي له أنواع يتصدّر سطر لكل نوع بكوده الخاص (الكود العام للصنف ما يُستخدم معاه)
      const rows = (data ?? []).flatMap((p) => (p.variants?.length
        ? p.variants.map((v) => ({
            "القسم": p.section_name,
            "اسم الصنف": `${p.name} - ${v.label}`,
            "وحدة البيع": p.unit,
            "السعر (د.ل)": Number(v.price),
            "الكمية المتوفرة": Number(v.stockQty),
            "رقم الصنف عندك (إجباري)": v.sku || "",
          }))
        : [{
            "القسم": p.section_name,
            "اسم الصنف": p.name,
            "وحدة البيع": p.unit,
            "السعر (د.ل)": Number(p.base_price),
            "الكمية المتوفرة": Number(p.stock_qty),
            "رقم الصنف عندك (إجباري)": p.supplier_sku || "",
          }]));
      const ws = XLSX.utils.json_to_sheet(rows);
      ws["!cols"] = [{ wch: 18 }, { wch: 30 }, { wch: 16 }, { wch: 14 }, { wch: 16 }, { wch: 26 }];
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "الأصناف");
      XLSX.writeFile(wb, `اصناف-${new Date().toISOString().slice(0, 10)}.xlsx`);
    }).finally(() => setExporting(false));
  }

  if (showVouchers) {
    return <StockVouchersScreen sections={sections} products={data ?? []}
      onClose={() => setShowVouchers(false)} onChanged={reload} />;
  }

  return (
    <div className="screen">
      <h2 className="section-heading">منتجاتك</h2>
      <p className="eyebrow-plain">عدّل السعر أو الكمية — تتحدث حالة التوفر تلقائيًا في الخادم.</p>

      <div className="search-bar">
        <Search size={16} />
        <input placeholder="ابحث في منتجاتك..." value={query} onChange={(e) => setQuery(e.target.value)} />
        {query && <button className="search-clear" onClick={() => setQuery("")}><X size={15} /></button>}
      </div>

      <div style={{ display: "flex", gap: 10, margin: "12px 0 16px", flexWrap: "wrap" }}>
        <button className="btn-primary" style={{ marginBottom: 0 }} onClick={() => setShowAdd((v) => !v)}>
          <Plus size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> {showAdd ? "إلغاء" : "إضافة صنف جديد"}
        </button>
        <button className="btn-ghost" style={{ marginBottom: 0 }} disabled={exporting || !data?.length}
          onClick={exportExcel}>
          <FileText size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} />
          {exporting ? "جارٍ التصدير…" : "تصدير كشف الأصناف Excel"}
        </button>
        <button className="btn-ghost" style={{ marginBottom: 0 }} onClick={() => setShowVouchers(true)}>
          <Wallet size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> فواتير المخزون
        </button>
        <button className="btn-ghost" style={{ marginBottom: 0 }} onClick={() => setShowBulkImages((v) => !v)}>
          <ImageIcon size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> {showBulkImages ? "إلغاء" : "رفع صور دفعة واحدة"}
        </button>
      </div>

      {showAdd && (
        <AddProductForm sections={sections ?? []} onClose={() => setShowAdd(false)}
          onCreated={(p) => { setData((list) => [...(list ?? []), p]); setShowAdd(false); }} />
      )}

      {showBulkImages && (
        <BulkImagesModal onClose={() => setShowBulkImages(false)} onDone={reload} />
      )}

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : (
        <div className="product-list">
          {visible.map((p) => (
            <ProductRow key={p.id} product={p}
              onSaved={(updated) => setData((list) => list.map((x) => x.id === updated.id ? updated : x))} />
          ))}
          {!visible.length && <Centered><p>لا توجد منتجات مطابقة</p></Centered>}
        </div>
      )}
    </div>
  );
}

function BulkImagesModal({ onClose, onDone }) {
  const [files, setFiles] = useState([]);
  const upload = useAction(() => api.uploadProductImagesBulk(files));
  const [result, setResult] = useState(null);
  const fileRef = useRef(null);

  return (
    <div className="detail-card voucher-form" style={{ marginTop: 16 }}>
      <h2 className="subsection-heading">رفع صور الأصناف دفعة واحدة</h2>
      <p className="hint">
        سمّ كل صورة باسم "رقم الصنف عندك" بالضبط (نفس اللي كتبته في حقل "رقم الصنف عندك" وقت إضافة الصنف)،
        مثلاً الصورة <code dir="ltr">SKU123.jpg</code> بتنحط تلقائيًا على الصنف اللي رقمه عندك SKU123.
        الأصناف اللي بلا رقم صنف ما تقدرش تستخدم هذي الطريقة.
      </p>
      <button type="button" className="btn-ghost" onClick={() => fileRef.current?.click()}>
        اختر الصور ({files.length})
      </button>
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" multiple
        style={{ display: "none" }} onChange={(e) => setFiles([...(e.target.files || [])])} />

      {upload.error && <p className="field-error">{upload.error}</p>}

      {result && (
        <div style={{ marginTop: 10 }}>
          <p className="hint">تم مطابقة {result.matched.length} صورة، وتعذّرت مطابقة {result.unmatched.length}.</p>
          {result.unmatched.length > 0 && (
            <ul style={{ fontSize: 13, color: "var(--danger, #a12626)" }}>
              {result.unmatched.map((u, i) => <li key={i}>{u.file} — {u.reason}</li>)}
            </ul>
          )}
        </div>
      )}

      <div className="add-form-actions">
        <button className="btn-primary" disabled={!files.length || upload.pending}
          onClick={() => upload.run().then((res) => { setResult(res); onDone(); }).catch(() => {})}>
          {upload.pending ? "جارٍ الرفع…" : "رفع ومطابقة"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إغلاق</button>
      </div>
    </div>
  );
}

