function StockVouchersScreen({ sections, products, onClose, onChanged }) {
  const [typeFilter, setTypeFilter] = useState("");
  const [range, setRange] = useState(EMPTY_RANGE);
  const [creating, setCreating] = useState(null); // "addition" | "discount" | null
  const [showImport, setShowImport] = useState(false);
  const [openId, setOpenId] = useState(null);
  const { data, loading, error, reload } = useFetch(
    (s) => api.stockVouchers({ ...(typeFilter ? { voucherType: typeFilter } : {}), ...rangeParams(range) }, s),
    [typeFilter, range.from, range.to]
  );

  const TYPE_LABELS = { addition: "إضافة", discount: "خصم" };

  if (openId) {
    return <StockVoucherDetail voucherId={openId} onClose={() => setOpenId(null)} />;
  }

  if (creating) {
    return (
      <StockVoucherForm voucherType={creating} products={products}
        onClose={() => setCreating(null)}
        onSaved={() => { setCreating(null); reload(); onChanged?.(); }} />
    );
  }

  if (showImport) {
    return (
      <ImportProductsView sections={sections} onClose={() => setShowImport(false)}
        onImported={() => { setShowImport(false); reload(); onChanged?.(); }} />
    );
  }

  return (
    <div className="screen">
      <div className="order-detail-head">
        <button className="icon-btn" onClick={onClose} aria-label="رجوع"><ArrowRight size={20} /></button>
        <span className="order-row-id">فواتير المخزون</span>
      </div>
      <p className="eyebrow-plain">كل عمليات إضافة أو خصم المخزون — يدويًا أو عبر استيراد إكسل — مسجّلة هنا كفواتير.</p>

      <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
        <button className="btn-primary" style={{ marginBottom: 0 }} onClick={() => setCreating("addition")}>
          <Plus size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> فاتورة إضافة
        </button>
        <button className="btn-ghost" style={{ marginBottom: 0 }} onClick={() => setCreating("discount")}>
          − فاتورة خصم
        </button>
        <button className="btn-ghost" style={{ marginBottom: 0 }} onClick={() => setShowImport(true)}>
          <Upload size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> استيراد من إكسل
        </button>
      </div>

      <DateRangeBar value={range} onChange={setRange} />

      <div className="chip-row" style={{ marginBottom: 12 }}>
        <button className={"chip" + (typeFilter === "" ? " chip-active" : "")} onClick={() => setTypeFilter("")}>الكل</button>
        <button className={"chip" + (typeFilter === "addition" ? " chip-active" : "")} onClick={() => setTypeFilter("addition")}>إضافة</button>
        <button className={"chip" + (typeFilter === "discount" ? " chip-active" : "")} onClick={() => setTypeFilter("discount")}>خصم</button>
      </div>

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !data?.length ? <Centered><p>لا توجد فواتير مسجّلة بعد</p></Centered>
       : (
        <div className="ledger-list">
          {data.map((v) => (
            <div className="ledger-row" key={v.id} style={{ cursor: "pointer" }} onClick={() => setOpenId(v.id)}>
              <span className={v.voucher_type === "addition" ? "cell-amount" : "cell-amount cell-debt"}>
                {v.voucher_type === "addition" ? "+" : "−"} {TYPE_LABELS[v.voucher_type]}
              </span>
              <span className="cell-id">{v.voucher_number}</span>
              <span className="cell-muted">{v.items_count} صنف · {v.reason}</span>
              <span className="cell-muted">{new Date(v.created_at).toLocaleDateString("ar")}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function StockVoucherForm({ voucherType, products, onClose, onSaved }) {
  const [query, setQuery] = useState("");
  const [cart, setCart] = useState([]); // [{ key, productId, variantId, name, unit, stockQty, qty }]
  const [reason, setReason] = useState("");
  const isIn = voucherType === "addition";

  const submit = useAction(() => api.createStockVoucher({
    voucherType,
    reason: reason.trim(),
    // الصنف ذو الأنواع يُحدَّد فيه النوع (variantId)، والصنف العادي بـ productId
    items: cart.map((c) => c.variantId
      ? { variantId: c.variantId, qty: Number(c.qty) }
      : { productId: c.productId, qty: Number(c.qty) }),
  }));

  // كل نوع يظهر كسطر مستقل (الكمية على مستوى النوع)، والصنف العادي كسطر واحد
  const entries = products.flatMap((p) => (p.variants?.length
    ? p.variants.map((v) => ({
        key: v.id, productId: p.id, variantId: v.id, name: `${p.name} — ${v.label}`,
        unit: p.unit, sku: v.sku, stockQty: v.stockQty,
      }))
    : [{ key: p.id, productId: p.id, variantId: null, name: p.name, unit: p.unit, sku: p.supplier_sku, stockQty: p.stock_qty }]));

  const q = query.trim();
  const results = q
    ? entries.filter((e) => !cart.some((c) => c.key === e.key)
        && (e.name.includes(q) || (e.sku && String(e.sku).includes(q))))
      .slice(0, 8)
    : [];

  function addToCart(e) {
    setCart((c) => [...c, { ...e, qty: 1 }]);
    setQuery("");
  }
  function setQty(key, qty) {
    setCart((c) => c.map((x) => x.key === key ? { ...x, qty } : x));
  }
  function removeFromCart(key) {
    setCart((c) => c.filter((x) => x.key !== key));
  }

  const valid = cart.length > 0 && cart.every((c) => Number(c.qty) > 0) && reason.trim().length >= 2;

  return (
    <div className="screen">
      <div className="order-detail-head">
        <button className="icon-btn" onClick={onClose} aria-label="رجوع"><ArrowRight size={20} /></button>
        <span className="order-row-id">{isIn ? "فاتورة إضافة جديدة" : "فاتورة خصم جديدة"}</span>
      </div>

      <label className="field-label">ابحث عن صنف بالاسم أو رقم الصنف عندك</label>
      <div className="search-bar">
        <Search size={16} />
        <input placeholder="اكتب للبحث..." value={query} onChange={(e) => setQuery(e.target.value)} />
      </div>
      {results.length > 0 && (
        <div className="ledger-list" style={{ marginBottom: 14 }}>
          {results.map((p) => (
            <div className="ledger-row" key={p.key} style={{ cursor: "pointer" }} onClick={() => addToCart(p)}>
              <span className="cell-id">{p.name}</span>
              <span className="cell-muted">{p.unit} {p.sku ? `· #${p.sku}` : ""}</span>
              <span className="cell-muted">الكمية الحالية: {p.stockQty}</span>
              <Plus size={16} />
            </div>
          ))}
        </div>
      )}

      {cart.length > 0 && (
        <div className="invoice-block" style={{ marginBottom: 14 }}>
          <div className="invoice-head">
            <span>الأصناف في الفاتورة</span>
            <span className="invoice-head-count">{cart.length} صنف</span>
          </div>
          {cart.map((c) => (
            <div className="supplier-item-row" key={c.key}>
              <div className="supplier-item-top">
                <span className="invoice-line-name">{c.name} <i>({c.unit})</i></span>
                <button className="link-btn" onClick={() => removeFromCart(c.key)}>حذف</button>
              </div>
              <span className="supplier-item-qty">الكمية الحالية بالمخزون: {c.stockQty}</span>
              <div className="confirmed-qty-row">
                <span>{isIn ? "الكمية المضافة:" : "الكمية المخصومة:"}</span>
                <input type="number" min="1" className="qty-input" value={c.qty}
                  onChange={(e) => setQty(c.key, Math.max(1, Number(e.target.value) || 1))} />
              </div>
            </div>
          ))}
        </div>
      )}

      <label className="field-label">سبب الفاتورة</label>
      <input className="field-input" placeholder={isIn ? "مثال: توريد جديد" : "مثال: تالف / جرد"}
        value={reason} onChange={(e) => setReason(e.target.value)} />

      {submit.error && <p className="field-error">{submit.error}</p>}

      <button className="btn-primary" disabled={!valid || submit.pending}
        onClick={() => submit.run().then(onSaved).catch(() => {})}>
        {submit.pending ? "جارٍ الحفظ…" : isIn ? "تأكيد فاتورة الإضافة" : "تأكيد فاتورة الخصم"}
      </button>
      <button className="btn-ghost" onClick={onClose}>إلغاء</button>
    </div>
  );
}

function StockVoucherDetail({ voucherId, onClose }) {
  const { data, loading, error } = useFetch(() => api.stockVoucher(voucherId), [voucherId]);

  function printPdf() {
    if (!data) return;
    const w = window.open("", "_blank");
    w.document.write(buildStockVoucherHTML(data));
    w.document.close();
  }

  return (
    <div className="screen">
      <div className="order-detail-head">
        <button className="icon-btn" onClick={onClose} aria-label="رجوع"><ArrowRight size={20} /></button>
        <span className="order-row-id">تفاصيل الفاتورة</span>
      </div>

      {loading ? <Spinner /> : error ? <p className="field-error">{error}</p> : data && (
        <>
          <div className="invoice-block" style={{ marginBottom: 14 }}>
            <div className="invoice-head">
              <span>{data.voucher.voucher_number}</span>
              <span className={data.voucher.voucher_type === "addition" ? "status-pill" : "status-pill status-pill-cancelled"}>
                {data.voucher.voucher_type === "addition" ? "فاتورة إضافة" : "فاتورة خصم"}
              </span>
            </div>
            <p className="order-row-meta">{data.voucher.reason}</p>
            <p className="order-row-meta">{new Date(data.voucher.created_at).toLocaleString("ar")}</p>
          </div>

          <table className="data-table">
            <thead><tr><th>الصنف</th><th>الوحدة</th><th>رقم الصنف</th><th>الكمية</th></tr></thead>
            <tbody>
              {data.lines.map((l) => (
                <tr key={l.id}>
                  <td className="cell-id">{l.product_name}{l.variant_label ? ` — ${l.variant_label}` : ""}</td>
                  <td className="cell-muted">{l.unit}</td>
                  <td className="cell-muted">{l.variant_sku || l.supplier_sku || "—"}</td>
                  <td className={Number(l.change_qty) >= 0 ? "cell-amount" : "cell-amount cell-debt"}>
                    {Number(l.change_qty) >= 0 ? "+" : ""}{l.change_qty}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          <button className="btn-primary" style={{ marginTop: 16 }} onClick={printPdf}>
            🖨️ طباعة / حفظ PDF
          </button>
        </>
      )}
    </div>
  );
}

function buildStockVoucherHTML(data) {
  const { voucher, lines } = data;
  const rows = lines.map((l, n) => `<tr><td>${n + 1}</td><td>${l.product_name}${l.variant_label ? ` — ${l.variant_label}` : ""}${(l.variant_sku || l.supplier_sku) ? ` <span class="sku">#${l.variant_sku || l.supplier_sku}</span>` : ""}</td>
    <td>${l.unit}</td><td>${Number(l.change_qty) >= 0 ? "+" : ""}${l.change_qty}</td></tr>`).join("");
  const title = voucher.voucher_type === "addition" ? "فاتورة إضافة مخزون" : "فاتورة خصم مخزون";

  return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"/>
<title>${title} — ${voucher.voucher_number}</title><style>
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@700;800&family=Tajawal:wght@400;500;700&display=swap');
*{box-sizing:border-box}body{font-family:'Tajawal',sans-serif;color:#17140f;margin:0;padding:32px;background:#fff}
.sheet{max-width:780px;margin:0 auto}
header{display:flex;justify-content:space-between;border-bottom:3px solid #ee4b15;padding-bottom:16px;margin-bottom:20px}
.brand{font-family:'Cairo',sans-serif;font-weight:800;font-size:26px;color:#ee4b15;margin:0}
.doc-title{font-family:'Cairo',sans-serif;font-weight:800;font-size:18px;text-align:left;margin:0}
.doc-meta{font-size:12px;color:#3a362a;text-align:left;margin-top:6px;line-height:1.8}
.sku{font-size:11px;color:#3a362a}
table{width:100%;border-collapse:collapse;margin-bottom:18px}
thead th{background:#efece3;border:1px solid #b8b09a;padding:9px;font-size:12px;text-align:right}
tbody td{border:1px solid #b8b09a;padding:9px;font-size:13px}
tbody td:first-child{width:40px;text-align:center;color:#3a362a}
.pdf-toolbar{position:sticky;top:0;z-index:10;display:flex;gap:10px;justify-content:center;
  background:#17140f;padding:10px;margin-bottom:20px}
.pdf-toolbar button{background:#ee4b15;color:#fff;border:none;padding:10px 18px;font-family:'Cairo',sans-serif;
  font-weight:700;font-size:13px;cursor:pointer;border-radius:4px}
.pdf-toolbar button:last-child{background:rgba(255,255,255,.15)}
@media print{.pdf-toolbar{display:none}}
@media print{body{padding:0}}
</style></head><body>
<div class="pdf-toolbar">
  <button onclick="window.print()">🖨️ طباعة / حفظ PDF</button>
  <button onclick="window.close()">✕ إغلاق</button>
</div>
<div class="sheet">
<header><img src="${LOGO_FULL}" alt="جملة" style="height:56px;width:auto;display:block"/>
<div><h2 class="doc-title">${title}</h2><div class="doc-meta">
رقم الفاتورة: <strong>${voucher.voucher_number}</strong><br/>التاريخ: ${new Date(voucher.created_at).toLocaleString("ar")}<br/>
السبب: ${voucher.reason || "—"}</div></div></header>
<table><thead><tr><th>#</th><th>الصنف</th><th>الوحدة</th><th>الكمية</th></tr></thead>
<tbody>${rows}</tbody></table>
</div></body></html>`;
}

// نافذة تكبير الصورة — تفتح عند الضغط على أي صورة صنف، وتُغلق بالضغط على × أو
// خارج الصورة أو مفتاح Escape
function Lightbox({ src, alt, onClose }) {
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <div className="lightbox-backdrop" onClick={onClose}>
      <button className="lightbox-close" onClick={onClose} aria-label="إغلاق"><X size={22} /></button>
      <img src={src} alt={alt || ""} onClick={(e) => e.stopPropagation()} />
    </div>
  );
}

function ProductRow({ product, onSaved }) {
  const [price, setPrice] = useState(product.base_price);
  const [sku, setSku] = useState(product.supplier_sku || "");
  const [showHistory, setShowHistory] = useState(false);
  const [showVariants, setShowVariants] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const [zoomed, setZoomed] = useState(false);
  const fileRef = useRef(null);
  const save = useAction(() => api.updateProduct(product.id, {
    basePrice: Number(price), supplierSku: sku.trim() || undefined,
  }));
  const dirty = Number(price) !== Number(product.base_price)
    || sku.trim() !== (product.supplier_sku || "");
  const st = stockTag(Number(product.stock_qty));

  function handlePhoto(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadError("");
    setUploading(true);
    api.uploadImage(file)
      .then((res) => api.updateProduct(product.id, { imageUrl: res.url }))
      .then(onSaved)
      .catch(() => setUploadError("تعذّر رفع الصورة"))
      .finally(() => setUploading(false));
  }

  return (
    <div className="supplier-product-row">
      <div className="supplier-product-top">
        <span className="product-name">{product.name}</span>
        <span className={"stock-tag stock-tag-" + st.tone}>{st.text}</span>
      </div>
      <span className="product-meta">
        {product.unit} · {product.section_name}
        {product.supplier_sku && <> · #{product.supplier_sku}</>}
      </span>
      {product.approval_status === "pending" && (
        <span className="stock-tag stock-tag-amber" style={{ marginTop: 4 }}>⏳ بانتظار موافقة الإدارة — لا يظهر للعميل بعد</span>
      )}
      {product.approval_status === "rejected" && (
        <span className="stock-tag stock-tag-red" style={{ marginTop: 4 }}>
          ❌ مرفوض من الإدارة{product.approval_note ? `: ${product.approval_note}` : ""}
        </span>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "8px 0" }}>
        {product.image_url
          ? <button onClick={() => setZoomed(true)} style={{ padding: 0, border: "none", cursor: "zoom-in" }}>
              <img src={product.image_url} alt="" style={{ width: 68, height: 68, objectFit: "cover", borderRadius: 10 }} />
            </button>
          : <div style={{ width: 68, height: 68, borderRadius: 10, background: "var(--paper)", display: "flex",
              alignItems: "center", justifyContent: "center", color: "var(--ink-soft)" }}><ImageIcon size={22} /></div>}
        <button className="link-btn" disabled={uploading} onClick={() => fileRef.current?.click()}>
          {uploading ? "جارٍ الرفع…" : product.image_url ? "تغيير الصورة" : "رفع صورة"}
        </button>
        <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp"
          style={{ display: "none" }} onChange={handlePhoto} />
      </div>
      {zoomed && <Lightbox src={product.image_url} alt={product.name} onClose={() => setZoomed(false)} />}
      {uploadError && <p className="field-error">{uploadError}</p>}

      <div className="supplier-product-fields">
        <label className="mini-field">
          <span>السعر (د.ل)</span>
          <input type="number" min="0" step="0.05" className="qty-input"
            value={price} onChange={(e) => setPrice(e.target.value)} />
        </label>
        <label className="mini-field">
          <span>رقم الصنف عندك</span>
          <input type="text" className="qty-input" style={{ width: 90 }}
            placeholder="إجباري" value={sku} onChange={(e) => setSku(e.target.value)} />
        </label>
        {dirty && (
          <button className="save-inline" disabled={save.pending}
            onClick={() => save.run().then(onSaved).catch(() => {})}>
            {save.pending ? "…" : <Check size={15} />}
          </button>
        )}
      </div>
      {save.error && <p className="field-error">{save.error}</p>}

      <div className="stock-row">
        <span className="stock-current">الكمية الحالية: <b>{product.stock_qty}</b></span>
        <button className="link-btn" onClick={() => setShowHistory(true)}>سجل الحركة</button>
        <button className="link-btn" onClick={() => setShowVariants((v) => !v)}>
          {showVariants ? "إخفاء الأنواع" : "أنواع الصنف (ألوان/مقاسات/عبوات)"}
        </button>
      </div>

      {showVariants && <VariantsManager product={product} />}

      {showHistory && (
        <StockHistoryModal product={product} onClose={() => setShowHistory(false)} />
      )}
    </div>
  );
}

function VariantsManager({ product }) {
  const { data, loading, error, reload } = useFetch(() => api.productVariants(product.id), [product.id]);
  const [showAdd, setShowAdd] = useState(false);

  return (
    <div className="detail-card voucher-form" style={{ marginTop: 8 }}>
      <p className="hint">
        كل نوع له سعره وكمية مخزونه الخاصين — مثلاً "أحمر - وسط" بسعر وكمية مختلفة عن "أزرق - كبير".
        لو أضفت أنواع هنا، العميل يختار من بينها بدل الصنف العادي.
      </p>
      {loading ? <Spinner /> : error ? <ErrorState message={error} onRetry={reload} /> : (
        !data?.length ? <p className="cell-muted">لا توجد أنواع بعد</p> : (
          <table className="data-table" style={{ marginTop: 0 }}>
            <thead><tr><th>النوع</th><th>السعر</th><th>الكمية</th><th>الحالة</th><th></th></tr></thead>
            <tbody>
              {data.map((v) => <VariantRow key={v.id} variant={v} onDone={reload} />)}
            </tbody>
          </table>
        )
      )}
      {showAdd ? (
        <AddVariantForm productId={product.id} onClose={() => setShowAdd(false)}
          onCreated={() => { reload(); setShowAdd(false); }} />
      ) : (
        <button className="chip chip-add" style={{ marginTop: 8 }} onClick={() => setShowAdd(true)}>
          <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> إضافة نوع جديد
        </button>
      )}
    </div>
  );
}

function VariantRow({ variant: v, onDone }) {
  const [price, setPrice] = useState(v.price);
  const [stockQty, setStockQty] = useState(v.stock_qty);
  const save = useAction(() => api.updateProductVariant(v.id, { price: Number(price), stockQty: Number(stockQty) }));
  const toggle = useAction(() => api.updateProductVariant(v.id, { isActive: !v.is_active }));
  const remove = useAction(() => api.deleteProductVariant(v.id));
  const dirty = Number(price) !== Number(v.price) || Number(stockQty) !== Number(v.stock_qty);

  return (
    <tr>
      <td className="cell-id">{v.label}</td>
      <td><input type="number" min="0" step="0.05" className="qty-input" style={{ width: 80 }}
        value={price} onChange={(e) => setPrice(e.target.value)} /></td>
      <td><input type="number" min="0" className="qty-input" style={{ width: 70 }}
        value={stockQty} onChange={(e) => setStockQty(e.target.value)} /></td>
      <td><span className={"status-pill" + (v.is_active ? " status-pill-approved" : "")}>
        {v.is_active ? "مفعّل" : "موقوف"}</span></td>
      <td style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
        {dirty && (
          <button className="save-inline" disabled={save.pending} onClick={() => save.run().then(onDone).catch(() => {})}>
            {save.pending ? "…" : <Check size={13} />}
          </button>
        )}
        <button className="invoice-action-btn" disabled={toggle.pending} onClick={() => toggle.run().then(onDone).catch(() => {})}>
          {v.is_active ? "إيقاف" : "تفعيل"}
        </button>
        <button className="invoice-action-btn" disabled={remove.pending}
          onClick={() => { if (window.confirm(`حذف النوع "${v.label}"؟`)) remove.run().then(onDone).catch(() => {}); }}>
          حذف
        </button>
        {(save.error || toggle.error || remove.error) && (
          <span className="field-error" style={{ flexBasis: "100%" }}>{save.error || toggle.error || remove.error}</span>
        )}
      </td>
    </tr>
  );
}

function AddVariantForm({ productId, onClose, onCreated }) {
  const [label, setLabel] = useState("");
  const [price, setPrice] = useState("");
  const [stockQty, setStockQty] = useState("0");
  const [sku, setSku] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);
  const create = useAction(() => api.createProductVariant(productId, {
    label: label.trim(), price: Number(price), stockQty: Number(stockQty) || 0,
    sku: sku.trim() || undefined, imageUrl: imageUrl || undefined,
  }));
  const valid = label.trim() && Number(price) > 0 && sku.trim();
  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    api.uploadImage(file).then((res) => setImageUrl(res.url)).catch(() => {}).finally(() => setUploading(false));
  }

  return (
    <div style={{ marginTop: 10 }}>
      <label className="field-label">اسم النوع (مثال: أحمر - وسط - كرتونة)</label>
      <input className="field-input" value={label} onChange={(e) => setLabel(e.target.value)} />
      <label className="field-label">السعر (د.ل)</label>
      <input className="field-input" type="number" min="0" step="0.05" value={price} onChange={(e) => setPrice(e.target.value)} />
      <label className="field-label">الكمية المتوفرة</label>
      <input className="field-input" type="number" min="0" value={stockQty} onChange={(e) => setStockQty(e.target.value)} />
      <label className="field-label">كود النوع (إجباري) + صورة</label>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
        <input className="field-input" style={{ marginBottom: 0, flex: 1 }} value={sku} onChange={(e) => setSku(e.target.value)} dir="ltr" />
        {imageUrl
          ? <img src={imageUrl} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }} onClick={() => setImageUrl("")} title="اضغط للإزالة" />
          : <button type="button" className="btn-ghost" style={{ width: "auto" }} disabled={uploading} onClick={() => fileRef.current?.click()}>
              {uploading ? "…" : "📷 صورة"}
            </button>}
        <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
      </div>
      {create.error && <p className="field-error">{create.error}</p>}
      <div className="add-form-actions">
        <button className="btn-primary" disabled={!valid || create.pending || uploading}
          onClick={() => create.run().then(onCreated).catch(() => {})}>
          {create.pending ? "جارٍ الحفظ…" : "حفظ النوع"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

function StockHistoryModal({ product, onClose }) {
  const [range, setRange] = useState(EMPTY_RANGE);
  const { data, loading, error } = useFetch(
    () => api.stockHistory(product.id, rangeParams(range)), [product.id, range.from, range.to]);

  return (
    <div className="login-card" style={{ marginTop: 10 }}>
      <div className="invoice-head" style={{ padding: "0 0 10px" }}>
        <span>سجل حركة: {product.name}</span>
        <button className="link-btn" onClick={onClose}>إغلاق</button>
      </div>
      <DateRangeBar value={range} onChange={setRange} />
      {loading ? <Spinner /> : error ? <p className="field-error">{error}</p> : (
        !data?.length ? <p className="hint">{range.from || range.to ? "لا توجد حركات في هذه الفترة" : "لا توجد حركات مسجّلة بعد"}</p> : (
          <div className="ledger-list">
            {data.map((m) => (
              <div className="order-row" key={m.id} style={{ cursor: "default" }}>
                <div className="order-row-top">
                  <span className="order-row-id">{m.variant_label ? `[${m.variant_label}] ` : ""}{m.reason}</span>
                  <span className={"status-pill" + (Number(m.change_qty) < 0 ? " status-pill-debit" : "")}>
                    {Number(m.change_qty) > 0 ? "+" : ""}{m.change_qty}
                  </span>
                </div>
                <span className="order-row-meta">{String(m.created_at).slice(0, 10)}</span>
              </div>
            ))}
          </div>
        )
      )}
    </div>
  );
}

// منشئ الأنواع (ألوان/مقاسات/عبوات) داخل نموذج إضافة الصنف نفسه — كل نوع سطر: الاسم، السعر، الكمية، كود المورد، صورة
function VariantsBuilder({ value, onChange }) {
  const setRow = (i, patch) => onChange(value.map((r, idx) => (idx === i ? { ...r, ...patch } : r)));
  const addRow = () => onChange([...value, { label: "", price: "", stockQty: "", sku: "", imageUrl: "" }]);
  const removeRow = (i) => onChange(value.filter((_, idx) => idx !== i));
  const [uploadingIdx, setUploadingIdx] = useState(null);

  function pickImage(i, e) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setUploadingIdx(i);
    api.uploadImage(file)
      .then((res) => setRow(i, { imageUrl: res.url }))
      .catch(() => {})
      .finally(() => setUploadingIdx(null));
  }

  const total = value.reduce((s, r) => s + (Number(r.stockQty) || 0), 0);

  return (
    <div style={{ marginBottom: 12 }}>
      {value.map((r, i) => (
        <div key={i} className="detail-card" style={{ padding: 10, marginBottom: 8 }}>
          <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 6 }}>
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} placeholder="النوع (مثال: أحمر - وسط)"
              value={r.label} onChange={(e) => setRow(i, { label: e.target.value })} />
            <button type="button" className="link-btn" onClick={() => removeRow(i)}>حذف</button>
          </div>
          <div style={{ display: "flex", gap: 8, marginBottom: 6 }}>
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} type="number" min="0" step="0.05" placeholder="السعر"
              value={r.price} onChange={(e) => setRow(i, { price: e.target.value })} />
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} type="number" min="0" placeholder="الكمية"
              value={r.stockQty} onChange={(e) => setRow(i, { stockQty: e.target.value })} />
          </div>
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} dir="ltr" placeholder="كود النوع (إجباري)"
              value={r.sku} onChange={(e) => setRow(i, { sku: e.target.value })} />
            {r.imageUrl
              ? <img src={r.imageUrl} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }}
                  onClick={() => setRow(i, { imageUrl: "" })} title="اضغط للإزالة" />
              : (
                <label className="btn-ghost" style={{ width: "auto", cursor: "pointer", margin: 0 }}>
                  {uploadingIdx === i ? "…" : "📷 صورة"}
                  <input type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={(e) => pickImage(i, e)} />
                </label>
              )}
          </div>
        </div>
      ))}
      <button type="button" className="chip chip-add" onClick={addRow}>+ إضافة نوع</button>
      {value.length > 0 && <p className="hint" style={{ marginTop: 6 }}>إجمالي كمية الصنف = مجموع الأنواع: <b>{total}</b></p>}
    </div>
  );
}

function AddProductForm({ sections, onClose, onCreated }) {
  const [form, setForm] = useState({ sectionId: "", name: "", unit: "", basePrice: "", stockQty: "", supplierSku: "" });
  const [parentId, setParentId] = useState("");
  const { data: subsections } = useFetch(
    (signal) => (parentId ? api.sections({ parentId }, signal) : Promise.resolve([])),
    [parentId]
  );
  const [imageUrl, setImageUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const fileRef = useRef(null);

  const selectedParent = sections.find((s) => s.id === parentId);
  const needsSubsection = Boolean(selectedParent?.has_subsections);

  const [hasVariants, setHasVariants] = useState(false);
  const [variants, setVariants] = useState([{ label: "", price: "", stockQty: "", sku: "", imageUrl: "" }]);
  const variantsValid = !hasVariants || (variants.length > 0 &&
    variants.every((v) => v.label.trim() && Number(v.price) > 0 && v.sku.trim()) &&
    new Set(variants.map((v) => v.label.trim())).size === variants.length);

  const create = useAction(() => api.createProduct({
    sectionId: form.sectionId, name: form.name.trim(), unit: form.unit.trim(),
    ...(hasVariants
      ? { variants: variants.map((v) => ({ label: v.label.trim(), price: Number(v.price), stockQty: Number(v.stockQty) || 0,
          sku: v.sku.trim() || undefined, imageUrl: v.imageUrl || undefined })) }
      : { basePrice: Number(form.basePrice), stockQty: Number(form.stockQty) }),
    supplierSku: hasVariants ? undefined : (form.supplierSku.trim() || undefined),
    imageUrl: hasVariants ? undefined : (imageUrl || undefined),
  }));

  const valid = form.sectionId && form.name.trim() && form.unit.trim() && variantsValid && (hasVariants || (form.basePrice && form.supplierSku.trim()));
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadError("");
    setUploading(true);
    api.uploadImage(file)
      .then((res) => setImageUrl(res.url))
      .catch(() => setUploadError("تعذّر رفع الصورة — تحقق من الحجم (5 ميجا كحد أقصى) والنوع (jpg أو png أو webp)"))
      .finally(() => setUploading(false));
  }

  return (
    <div className="login-card" style={{ marginTop: 16 }}>
      <label className="field-label">القسم</label>
      <select className="field-input" value={parentId} onChange={(e) => {
        const val = e.target.value;
        setParentId(val);
        // القسم بلا تصنيفات فرعية: يُحفظ مباشرة كقسم الصنف
        const p = sections.find((s) => s.id === val);
        setForm((f) => ({ ...f, sectionId: p && !p.has_subsections ? val : "" }));
      }}>
        <option value="">اختر القسم</option>
        {sections.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
      </select>

      {needsSubsection && (
        <>
          <label className="field-label">التصنيف الفرعي</label>
          <select className="field-input" value={form.sectionId} onChange={set("sectionId")}>
            <option value="">اختر التصنيف الفرعي</option>
            {(subsections ?? []).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </>
      )}

      <label className="field-label">اسم الصنف</label>
      <input className="field-input" value={form.name} onChange={set("name")} />

      <label className="field-label">وحدة البيع</label>
      <input className="field-input" placeholder="مثال: كيس 50كغ" value={form.unit} onChange={set("unit")} />

      <label style={{ display: "flex", alignItems: "center", gap: 8, margin: "8px 0 12px" }}>
        <input type="checkbox" checked={hasVariants} onChange={(e) => setHasVariants(e.target.checked)} />
        <span>الصنف له ألوان أو مقاسات أو عبوات مختلفة</span>
      </label>

      {hasVariants ? (
        <VariantsBuilder value={variants} onChange={setVariants} />
      ) : (
        <>
          <label className="field-label">السعر (د.ل)</label>
          <input className="field-input" type="number" min="0" value={form.basePrice} onChange={set("basePrice")} />

          <label className="field-label">الكمية المتوفرة</label>
          <input className="field-input" type="number" min="0" value={form.stockQty} onChange={set("stockQty")} />
        </>
      )}

      {hasVariants ? (
        <p className="hint">كود وصورة كل نوع تضيفهم داخل النوع نفسه، وصورة أول نوع تصير صورة الصنف للعميل.</p>
      ) : (
        <>
      <label className="field-label">رقم الصنف عندك (إجباري)</label>
      <input className="field-input" placeholder="مثال: SKU-1042" value={form.supplierSku} onChange={set("supplierSku")} />

      <label className="field-label">صورة الصنف (اختياري)</label>
      {imageUrl ? (
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
          <img src={imageUrl} alt="" style={{ width: 56, height: 56, objectFit: "cover", borderRadius: 6 }} />
          <button className="link-btn" onClick={() => setImageUrl("")}>إزالة الصورة</button>
        </div>
      ) : (
        <button type="button" className="btn-ghost" disabled={uploading}
          onClick={() => fileRef.current?.click()} style={{ marginBottom: 12 }}>
          <ImageIcon size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} />
          {uploading ? "جارٍ الرفع…" : "رفع صورة"}
        </button>
      )}
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp"
        style={{ display: "none" }} onChange={handleFile} />
        </>
      )}
      {uploadError && <p className="field-error">{uploadError}</p>}

      {create.error && <p className="field-error">{create.error}</p>}

      <button className="btn-primary" disabled={!valid || uploading || create.pending}
        onClick={() => create.run().then(onCreated).catch(() => {})}>
        {create.pending ? "جارٍ الحفظ…" : "إضافة الصنف"}
      </button>
      <button className="btn-ghost" onClick={onClose}>إلغاء</button>
    </div>
  );
}

