// يحوّل رقم صحيح (٠ إلى تحت المليار) لنص عربي — يُستخدم لكتابة المبلغ بالحروف بالسند
const ONES_W = ["", "واحد", "اثنان", "ثلاثة", "أربعة", "خمسة", "ستة", "سبعة", "ثمانية", "تسعة"];
const TEENS_W = ["عشرة", "أحد عشر", "اثنا عشر", "ثلاثة عشر", "أربعة عشر", "خمسة عشر", "ستة عشر", "سبعة عشر", "ثمانية عشر", "تسعة عشر"];
const TENS_W = ["", "", "عشرون", "ثلاثون", "أربعون", "خمسون", "ستون", "سبعون", "ثمانون", "تسعون"];
const HUNDREDS_W = ["", "مئة", "مئتان", "ثلاثمئة", "أربعمئة", "خمسمئة", "ستمئة", "سبعمئة", "ثمانمئة", "تسعمئة"];
function threeDigitsToArabicWords(n) {
  if (n === 0) return "";
  const h = Math.floor(n / 100), rem = n % 100;
  const parts = [];
  if (h) parts.push(HUNDREDS_W[h]);
  if (rem) {
    if (rem < 10) parts.push(ONES_W[rem]);
    else if (rem < 20) parts.push(TEENS_W[rem - 10]);
    else {
      const t = Math.floor(rem / 10), o = rem % 10;
      parts.push(o ? `${ONES_W[o]} و${TENS_W[t]}` : TENS_W[t]);
    }
  }
  return parts.join(" و");
}
function numberToArabicWords(num) {
  num = Math.floor(num);
  if (num === 0) return "صفر";
  const scales = [
    { value: 1000000000, singular: "مليار", dual: "ملياران", plural: "مليارات" },
    { value: 1000000, singular: "مليون", dual: "مليونان", plural: "ملايين" },
    { value: 1000, singular: "ألف", dual: "ألفان", plural: "آلاف" },
  ];
  let n = num;
  const parts = [];
  for (const s of scales) {
    const count = Math.floor(n / s.value);
    if (count > 0) {
      if (count === 1) parts.push(s.singular);
      else if (count === 2) parts.push(s.dual);
      else if (count <= 10) parts.push(`${threeDigitsToArabicWords(count)} ${s.plural}`);
      else parts.push(`${threeDigitsToArabicWords(count)} ${s.singular}`);
      n -= count * s.value;
    }
  }
  if (n > 0) parts.push(threeDigitsToArabicWords(n));
  return parts.join(" و");
}
function amountInWords(amount) {
  const dinars = Math.floor(Number(amount));
  const dirhams = Math.round((Number(amount) - dinars) * 100);
  let text = `${numberToArabicWords(dinars)} دينار`;
  if (dirhams > 0) text += ` و${numberToArabicWords(dirhams)} درهم`;
  return `${text} فقط لا غير`;
}

function buildVoucherHTML(v, balance) {
  const typeLabel = v.voucher_type === "receipt" ? "سند قبض" : "سند صرف";
  const methodLabel = v.method === "cash" ? "نقدًا" : v.method === "transfer" ? "حوالة مصرفية" : "بطاقة";
  const balanceLabel = balance == null ? null
    : balance > 0 ? `له ${money(balance)}` : balance < 0 ? `عليه ${money(Math.abs(balance))}` : "صفر";
  return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@700;800&family=Tajawal:wght@400;500;700&display=swap');
  body{font-family:'Tajawal',sans-serif;padding:0;margin:0;background:#f4f5f9;color:#181d2a}
  .pdf-toolbar{position:sticky;top:0;z-index:10;display:flex;gap:10px;justify-content:center;
    background:#181d2a;padding:14px}
  .pdf-toolbar button{background:#ff6a1a;color:#fff;border:none;padding:10px 20px;
    font-family:'Cairo',sans-serif;font-weight:700;font-size:13px;cursor:pointer;border-radius:999px}
  .pdf-toolbar button:last-child{background:rgba(255,255,255,.15)}
  .sheet{max-width:480px;margin:28px auto;background:#fff;border-radius:20px;padding:28px;
    box-shadow:0 1px 3px rgba(24,29,42,.06),0 1px 2px rgba(24,29,42,.04)}
  .center{display:flex;flex-direction:column;align-items:center}
  .logo{height:44px;width:auto;display:block;margin-bottom:10px}
  .badge{display:inline-block;background:#ff6a1a;color:#fff;font-family:'Cairo',sans-serif;font-weight:700;
    font-size:11.5px;border-radius:999px;padding:5px 14px;margin-bottom:10px}
  h1{font-family:'Cairo',sans-serif;font-size:20px;text-align:center;margin:0 0 4px;color:#181d2a}
  .sub{text-align:center;color:#6b7280;font-size:12px;margin:0 0 20px}
  .row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #ecedf2;font-size:14px}
  .words{font-size:12.5px;color:#6b7280;padding:10px 0;border-bottom:1px solid #ecedf2}
  .total{font-family:'Cairo',sans-serif;font-weight:800;font-size:18px;color:#fff;
    background:#181d2a;border-radius:14px;margin-top:14px;padding:14px 16px;border-bottom:none}
  @media print{.pdf-toolbar{display:none}body{background:#fff}.sheet{margin:0;box-shadow:none;border-radius:0}}
</style></head><body>
<div class="pdf-toolbar">
  <button onclick="window.print()">🖨️ طباعة / حفظ PDF</button>
  <button onclick="window.close()">✕ إغلاق</button>
</div>
<div class="sheet">
  <div class="center"><img class="logo" src="${LOGO_FULL}" alt="جملة"/><span class="badge">${typeLabel}</span></div>
  <p class="sub">رقم السند: ${v.voucher_number}</p>
  <div class="row"><span>التاريخ</span><span>${String(v.created_at || v.approved_at).slice(0, 10)}</span></div>
  <div class="row"><span>الطرف</span><span>${esc(v.party_name)}</span></div>
  ${balanceLabel ? `<div class="row"><span>الرصيد الحالي</span><span>${balanceLabel}</span></div>` : ""}
  <div class="row"><span>طريقة الدفع</span><span>${methodLabel}</span></div>
  ${v.note ? `<div class="row"><span>ملاحظة</span><span>${esc(v.note)}</span></div>` : ""}
  <p class="words">المبلغ كتابةً: ${amountInWords(v.amount)}</p>
  <div class="row total"><span>المبلغ</span><span>${Number(v.amount).toFixed(2)} د.ل</span></div>
</div>
</body></html>`;
}

function openVoucherPdf(id) {
  // نفتح النافذة فورًا مع الضغطة (قبل انتظار الشبكة) عشان ما تنحظرش كنافذة منبثقة
  const w = window.open("", "_blank");
  if (!w) return alert("يرجى السماح بالنوافذ المنبثقة لعرض الإيصال.");
  w.document.write("<p style='font-family:sans-serif;padding:24px'>جارٍ التحميل…</p>");
  api.voucherData(id).then(async (v) => {
    let balance = null;
    try {
      const rows = await api.supplierLedger(v.party_id);
      balance = rows.length ? Number(rows[rows.length - 1].balance) : 0;
    } catch { /* لو تعذّر جلب الرصيد، نطبع السند بدونه */ }

    w.document.open(); w.document.write(buildVoucherHTML(v, balance)); w.document.close();
  }).catch(() => { w.close(); alert("تعذّر تحميل بيانات الإيصال"); });
}

function LedgerView({ supplierId }) {
  const [tab, setTab] = useState("orders");
  const [query, setQuery] = useState("");
  const [range, setRange] = useState(EMPTY_RANGE);
  const orders = useFetch((signal) => api.orders(rangeParams(range), signal), [range.from, range.to]);
  const ledger = useFetch(() => api.supplierLedger(supplierId, rangeParams(range)), [supplierId, range.from, range.to]);
  const rows = ledger.data ?? [];
  const balance = rows.length ? Number(rows[rows.length - 1].balance) : 0;

  const parts = (orders.data ?? []).filter(
    (p) => !query.trim() || String(p.order_number).toLowerCase().includes(query.trim().toLowerCase())
  );
  const totalPaid = rows.filter((e) => !e.is_opening).reduce((sum, e) => sum + Number(e.debit || 0), 0);
  const totalSales = (orders.data ?? [])
    .filter((p) => p.status !== "cancelled")
    .reduce((sum, p) => sum + Number(p.subtotal || 0), 0);

  return (
    <div className="screen">
      <h2 className="section-heading">كشف الحساب</h2>

      <div className="chip-row">
        <button className={"chip" + (tab === "orders" ? " chip-active" : "")} onClick={() => setTab("orders")}>
          الفواتير
        </button>
        <button className={"chip" + (tab === "ledger" ? " chip-active" : "")} onClick={() => setTab("ledger")}>
          حركة الحساب
        </button>
        <button className={"chip" + (tab === "vouchers" ? " chip-active" : "")} onClick={() => setTab("vouchers")}>
          سنداتي
        </button>
      </div>

      <DateRangeBar value={range} onChange={setRange} />

      {tab === "orders" ? (
        orders.loading ? <Spinner />
        : orders.error ? <ErrorState message={orders.error} onRetry={orders.reload} />
        : !orders.data?.length ? <Centered><Package size={26} /><p>{range.from || range.to ? "لا توجد فواتير في هذه الفترة" : "لا توجد فواتير بعد"}</p></Centered>
        : (
          <>
            <div className="stat-grid" style={{ gridTemplateColumns: "1fr 1fr 1fr" }}>
              <div className="stat-box"><span>إجمالي المبيعات</span><b>{money(totalSales)}</b></div>
              <div className="stat-box"><span>المدفوع لك</span><b>{ledger.loading ? "…" : money(totalPaid)}</b></div>
              {ledger.loading ? (
                <div className="stat-box"><span>الرصيد</span><b>…</b></div>
              ) : balance > 0 ? (
                <div className="stat-box stat-box-credit"><span>المتبقي لك</span><b>{money(balance)}</b></div>
              ) : balance < 0 ? (
                <div className="stat-box stat-box-debt"><span>المتبقي عليك</span><b>{money(Math.abs(balance))}</b></div>
              ) : (
                <div className="stat-box"><span>الرصيد</span><b>{money(0)}</b></div>
              )}
            </div>

            <div className="search-bar">
              <Search size={16} />
              <input placeholder="ابحث برقم الفاتورة..." value={query}
                onChange={(e) => setQuery(e.target.value)} dir="ltr" style={{ textAlign: "right" }} />
              {query && <button className="search-clear" onClick={() => setQuery("")}><X size={15} /></button>}
            </div>

            <div className="ledger-list">
              {parts.map((p) => {
                const cancelled = p.status === "cancelled";
                const done = ["closed", "picked_up"].includes(p.status);
                return (
                  <div className={"order-row" + (cancelled ? " order-row-cancelled" : "")} key={p.order_supplier_id}>
                    <div className="order-row-top">
                      <span className="order-row-id">{p.order_number}</span>
                      <span className={"status-pill" + (cancelled ? " status-pill-cancelled" : "")}>{partLabel(p.status)}</span>
                    </div>
                    <span className="order-row-meta">
                      {String(p.created_at).slice(0, 10)} · {p.customer_name} · {p.fulfillment === "pickup" ? "استلام شخصي" : "توصيل"}
                    </span>
                    <div className="order-row-bottom">
                      <span className={done ? "pay-status pay-status-success" : "pay-status pay-status-amber"}>
                        {cancelled ? "ملغاة" : done ? "مكتملة" : "قيد التنفيذ"}
                      </span>
                      <span className="order-row-total">{money(p.subtotal)}</span>
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        )
      ) : tab === "ledger" ? (
        ledger.loading ? <Spinner /> : ledger.error ? <ErrorState message={ledger.error} onRetry={ledger.reload} /> : (
          <div className="items-report">
            <button className="btn-ghost" style={{ marginBottom: 10 }}
              onClick={() => openLedgerStatement({
                title: "كشف حساب المورد", partyName: "حسابي", rows, period: rangeLabel(range),
                balanceLabel: balance > 0 ? `المستحق لك: ${money(balance)}` : balance < 0 ? `عليك للشركة: ${money(Math.abs(balance))}` : "الرصيد: متوازن",
              })}>🖨️ طباعة / PDF لكشف الحساب</button>
            {rows.map((e, i) => (
              <div className="item-tx-row" key={i} style={e.is_opening ? { fontWeight: 700 } : undefined}>
                <span className="item-tx-date">{String(e.entry_date).slice(0, 10)}</span>
                <span className="item-tx-qty">{e.label || "حركة مالية"}{e.voucher_number ? ` — ${e.voucher_number}` : ""}</span>
                <span className="item-tx-price">
                  {Number(e.debit) > 0 ? `مدين ${money(e.debit)}` : `دائن ${money(e.credit)}`}
                </span>
              </div>
            ))}
            {!rows.length && <Centered><p>لا توجد حركة بعد</p></Centered>}
          </div>
        )
      ) : (
        <MyVouchersPanel range={range} />
      )}
    </div>
  );
}

function MyVouchersPanel({ range }) {
  const { data, loading, error, reload } = useFetch(() => api.myVouchers(rangeParams(range)), [range?.from, range?.to]);
  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;
  if (!data?.length) return <Centered><p>لا توجد سندات بعد</p></Centered>;

  return (
    <div className="items-report">
      {data.map((v) => (
        <div className="item-tx-row" key={v.id}>
          <span className="item-tx-date">{String(v.created_at).slice(0, 10)}</span>
          <span className="item-tx-qty">
            {v.voucher_type === "receipt" ? "سند قبض" : "سند صرف"} {v.voucher_number} — {money(v.amount)}
          </span>
          <button className="link-btn" onClick={() => openVoucherPdf(v.id)}>PDF</button>
        </div>
      ))}
    </div>
  );
}

